// One item per listing photo, in walkthrough order.
// Browsers don't always keep the order you picked files in, so photos are sorted by file name
// when sort_photos_by_file_name is on: name them 01-entry.jpg, 02-living.jpg, 03-kitchen.jpg ...
const s = $('Set Walkthrough Configurations').first().json;
const form = $('When Listing Submitted Trigger').first();
let photos = Object.values(form.binary || {}).filter(b => String(b.mimeType || '').startsWith('image/'));
if (s.sort_photos_by_file_name === true || s.sort_photos_by_file_name === 'true') {
  photos = [...photos].sort((a, b) => String(a.fileName || '').localeCompare(String(b.fileName || ''), undefined, { numeric: true, sensitivity: 'base' }));
}
const ext = { 'image/png': 'png', 'image/webp': 'webp' };
return photos.map((photo, i) => ({
  json: {
    photo_number: i + 1,
    file_name: photo.fileName || `photo_${i + 1}.${ext[photo.mimeType] || 'jpg'}`,
    mime_type: photo.mimeType || 'image/jpeg',
  },
  binary: { photo },
}));

// Reads each photo's pixel size from its file header (JPEG, PNG, WebP) and plans a centered 9:16 crop.
// Kling 3.0 takes the video's aspect ratio from the start image, so vertical photos give a vertical video.
const s = $('Set Walkthrough Configurations').first().json;
const target = 9 / 16;
const cropOn = s.crop_to_vertical === true || s.crop_to_vertical === 'true';

function exifOrientation(buf, t) {
  const le = buf.toString('ascii', t, t + 2) === 'II';
  const u16 = o => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = o => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const ifd = t + u32(t + 4);
  const count = u16(ifd);
  for (let k = 0; k < count; k++) {
    const e = ifd + 2 + k * 12;
    if (u16(e) === 0x0112) return u16(e + 8);
  }
  return 1;
}

function imageSize(buf) {
  try {
    if (buf[0] === 0x89 && buf.toString('ascii', 1, 4) === 'PNG') {
      return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20), orientation: 1 };
    }
    if (buf.toString('ascii', 0, 4) === 'RIFF' && buf.toString('ascii', 8, 12) === 'WEBP') {
      const kind = buf.toString('ascii', 12, 16);
      if (kind === 'VP8X') return { w: 1 + buf.readUIntLE(24, 3), h: 1 + buf.readUIntLE(27, 3), orientation: 1 };
      if (kind === 'VP8L') { const b = buf.readUInt32LE(21); return { w: (b & 0x3fff) + 1, h: ((b >> 14) & 0x3fff) + 1, orientation: 1 }; }
      if (kind === 'VP8 ') return { w: buf.readUInt16LE(26) & 0x3fff, h: buf.readUInt16LE(28) & 0x3fff, orientation: 1 };
    }
    if (buf[0] === 0xff && buf[1] === 0xd8) {
      let i = 2;
      let orientation = 1;
      while (i + 9 < buf.length) {
        if (buf[i] !== 0xff) { i++; continue; }
        const marker = buf[i + 1];
        if (marker === 0xff) { i++; continue; }
        if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd8)) { i += 2; continue; }
        const len = buf.readUInt16BE(i + 2);
        if (marker === 0xe1 && buf.toString('ascii', i + 4, i + 8) === 'Exif') {
          try { orientation = exifOrientation(buf, i + 10) || 1; } catch (e) { orientation = 1; }
        }
        if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker)) {
          return { w: buf.readUInt16BE(i + 7), h: buf.readUInt16BE(i + 5), orientation };
        }
        i += 2 + len;
      }
    }
  } catch (e) {}
  return null;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buf = await this.helpers.getBinaryDataBuffer(i, 'photo');
  const size = imageSize(buf);
  let crop = { x_percent: 0, y_percent: 0, width_percent: 100, height_percent: 100 };
  let problem = null;
  let w = null;
  let h = null;
  if (!size || !size.w || !size.h) {
    problem = `Photo ${item.json.photo_number} (${item.json.file_name}): could not read the image size. Use JPG, PNG or WebP.`;
  } else {
    // EXIF orientations 5-8 mean the camera stored the photo rotated by 90 degrees.
    const rotated = size.orientation >= 5 && size.orientation <= 8;
    w = rotated ? size.h : size.w;
    h = rotated ? size.w : size.h;
    const ratio = w / h;
    if (cropOn && ratio > target * 1.01) {
      const wp = (target / ratio) * 100;
      crop = { x_percent: Math.round(((100 - wp) / 2) * 1000) / 1000, y_percent: 0, width_percent: Math.round(wp * 1000) / 1000, height_percent: 100 };
    } else if (cropOn && ratio < target * 0.99) {
      const hp = (ratio / target) * 100;
      crop = { x_percent: 0, y_percent: Math.round(((100 - hp) / 2) * 1000) / 1000, width_percent: 100, height_percent: Math.round(hp * 1000) / 1000 };
    }
    const outW = (w * crop.width_percent) / 100;
    const outH = (h * crop.height_percent) / 100;
    if (outW < 300 || outH < 300) problem = `Photo ${item.json.photo_number} (${item.json.file_name}) is too small: Kling needs at least 300 x 300 px after cropping.`;
    if (!cropOn && (w / h < 0.4 || w / h > 2.5)) problem = `Photo ${item.json.photo_number} (${item.json.file_name}) has an aspect ratio Kling does not accept (0.4 to 2.5).`;
  }
  out.push({ json: { ...item.json, width: w, height: h, ...crop, size_problem: problem }, binary: item.binary });
}
return out;

// fal returned one upload URL per photo. Put each photo back next to its URL for the upload step.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const photos = $('Plan Vertical Crop for Photos').all();
return $input.all().map((item, i) => ({
  json: {
    ...photos[i].json,
    upload_url: item.json.upload_url || '',
    file_url: item.json.file_url || '',
    upload_error: item.json.upload_url ? '' : errText(item.json.error) || 'no upload URL returned',
  },
  binary: photos[i].binary,
}));

// Checks every photo made it to fal, then pairs neighbours: clip 1 = photo 1 -> photo 2, clip 2 = photo 2 -> photo 3, ...
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Set Walkthrough Configurations').first().json;
const photos = $('Prepare Photos for Upload').all().map(p => p.json);
const uploads = $('Put Photo to fal Storage').all().map(p => p.json);
const crops = $input.all().map(c => c.json);
const problems = [];
const frames = photos.map((p, i) => {
  const crop = crops[i] || {};
  const url = crop.image && crop.image.url;
  const label = `Photo ${p.photo_number} (${p.file_name})`;
  if (p.size_problem) problems.push(p.size_problem);
  else if (p.upload_error) problems.push(`${label}: fal storage did not return an upload URL (${p.upload_error}).`);
  else if (uploads[i] && uploads[i].error) problems.push(`${label}: upload to fal storage failed (${errText(uploads[i].error)}).`);
  else if (!url) problems.push(`${label}: fal could not crop the photo (${errText(crop.error) || 'no image URL returned'}).`);
  return { photo_number: p.photo_number, file_name: p.file_name, image_url: url || '' };
});
if (problems.length) {
  return [{ json: { route: 'error', ok: false, stage: 'Photo upload', problems } }];
}
const useAi = s.use_openai === true || s.use_openai === 'true';
const pairs = [];
for (let i = 0; i < frames.length - 1; i++) {
  pairs.push({
    json: {
      route: useAi ? 'ai' : 'template',
      ok: true,
      pair_number: i + 1,
      pair_count: frames.length - 1,
      start_photo: frames[i].file_name,
      end_photo: frames[i + 1].file_name,
      start_image_url: frames[i].image_url,
      end_image_url: frames[i + 1].image_url,
    },
  });
}
return pairs;

