// One item with every room pair and its AI camera prompt.
// If OpenAI failed for a pair, that pair falls back to the default camera prompt from the settings.
const s = $('Set Walkthrough Configurations').first().json;
const pairs = $('Pair Photos into Clips').all().map(p => p.json);
const outs = $input.all().map(o => (o.json && o.json.output) || {});
let fallbacks = 0;
const merged = pairs.map((p, i) => {
  const o = outs[i] || {};
  let prompt = typeof o.camera_prompt === 'string' ? o.camera_prompt.trim() : '';
  if (!prompt) {
    fallbacks++;
    prompt = String(s.default_camera_prompt || '').trim();
  }
  return {
    ...p,
    start_room: String(o.start_room || p.start_photo).slice(0, 60),
    end_room: String(o.end_room || p.end_photo).slice(0, 60),
    camera_prompt: prompt.slice(0, 1800),
  };
});
const rooms = [merged[0].start_room, ...merged.map(p => p.end_room)];
return [{ json: { pairs: merged, rooms, ai_prompt_fallbacks: fallbacks } }];

