// Builds one fal request per room pair and the captions for every network.
// The AI label line and your footer are added here, so they are always present.
const s = $('Set Walkthrough Configurations').first().json;
const f = $('When Listing Submitted Trigger').first().json;
const aiRan = $('Generate Listing Captions').isExecuted;
const guard = String(s.prompt_guardrails || '').trim();
let pairs;
let rooms = [];
let ai = {};
let promptSource = 'default prompt';
let aiFallbacks = 0;
if (aiRan) {
  const notes = $('Aggregate Room Notes').first().json;
  pairs = notes.pairs;
  rooms = notes.rooms || [];
  aiFallbacks = notes.ai_prompt_fallbacks || 0;
  ai = ($input.first().json && $input.first().json.output) || {};
  promptSource = aiFallbacks ? `OpenAI (${aiFallbacks} pair(s) used the default prompt)` : 'OpenAI';
} else {
  pairs = $input.all().map(item => ({ ...item.json, camera_prompt: String(s.default_camera_prompt || '').trim() }));
}

// ---- captions
const clean = v => String(v || '').trim();
const address = clean(f['Property Address']);
const facts = [clean(f['Asking Price']), clean(f['Bedrooms']) && `${clean(f['Bedrooms'])} bed`, clean(f['Bathrooms']) && `${clean(f['Bathrooms'])} bath`, clean(f['Interior Size'])].filter(Boolean);
const features = clean(f['Key Features']).split(/\n|;/).map(t => t.replace(/^[-*\u2022\s]+/, '').trim()).filter(Boolean).slice(0, 4);
const agent = clean(f['Agent and Brokerage']);
const link = clean(f['Listing Link']);
const tags = clean(s.extra_hashtags);
const label = clean(s.ai_label_line);
const footer = clean(s.brokerage_footer);
const tail = [label, footer].filter(Boolean).join('\n');
const intro = `Walk through ${address}${facts.length ? ` | ${facts.join(' | ')}` : ''}`;
const template = {
  tiktok: [intro, features.join(' | '), agent, tags].filter(Boolean).join('\n'),
  instagram: [intro, features.map(t => `- ${t}`).join('\n'), link ? `Details: ${link}` : 'Details in bio', `Listed by ${agent}`, tags].filter(Boolean).join('\n\n'),
  facebook: [intro, features.map(t => `- ${t}`).join('\n'), link ? `Full listing: ${link}` : '', `Listed by ${agent}`].filter(Boolean).join('\n\n'),
  linkedin: [`New listing: ${address}`, facts.join(' | '), features.join(' | '), link ? `Full listing: ${link}` : '', `Listed by ${agent}`].filter(Boolean).join('\n\n'),
};
const pick = (key, aiKey, max) => {
  const body = clean(ai[aiKey]) || template[key];
  const room = max - tail.length - 2;
  return `${body.slice(0, room)}\n\n${tail}`.trim();
};
const captions = {
  tiktok: pick('tiktok', 'tiktok_caption', 2200),
  instagram: pick('instagram', 'instagram_caption', 2200),
  facebook: pick('facebook', 'facebook_caption', 5000),
  linkedin: pick('linkedin', 'linkedin_caption', 3000),
  source: clean(ai.tiktok_caption) ? 'OpenAI' : 'template',
};

// ---- fal requests (field names from the fal OpenAPI schema of the endpoint in video_model)
const isV3 = /kling-video\/v3\//.test(String(s.video_model));
return pairs.map(p => {
  // Kling 3.0 takes duration as one of the strings "3".."15". The Kling 4.0 schema on fal
  // takes an integer (3-30), so the type follows the endpoint.
  const body = {
    prompt: `${p.camera_prompt} ${guard}`.trim().slice(0, 2500),
    start_image_url: p.start_image_url,
    end_image_url: p.end_image_url,
    duration: isV3 ? String(s.clip_seconds) : Number(s.clip_seconds),
  };
  if (isV3) {
    body.generate_audio = s.generate_audio === true || s.generate_audio === 'true';
    body.negative_prompt = String(s.negative_prompt || '');
    body.cfg_scale = Number(s.cfg_scale);
  }
  return {
    json: {
      pair_number: p.pair_number,
      clip_label: `${p.start_room || p.start_photo} -> ${p.end_room || p.end_photo}`,
      model: s.video_model,
      body,
      captions,
      rooms,
      prompt_source: promptSource,
    },
  };
});

// Every clip job must have a request id from fal. If one failed, the others are canceled.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const requests = $('Prepare Clip Requests for Kling').all().map(r => r.json);
const subs = $input.all().map(r => r.json || {});
const problems = [];
const jobs = [];
const now = Date.now();
requests.forEach((r, i) => {
  const j = subs[i] || {};
  if (!j.request_id || !j.status_url || !j.response_url) {
    problems.push(`Clip ${r.pair_number} (${r.clip_label}): fal did not accept the job (${errText(j.error) || errText(j.detail) || 'no request id'}).`);
  } else {
    jobs.push({ ok: true, pair_number: r.pair_number, clip_label: r.clip_label, request_id: j.request_id, status_url: j.status_url, response_url: j.response_url, cancel_url: j.cancel_url || `${j.response_url}/cancel`, submitted_at: now });
  }
});
if (problems.length) {
  const stage = 'Kling submit';
  if (!jobs.length) return [{ json: { ok: false, stage, problems, cancel_url: '' } }];
  return jobs.map(job => ({ json: { ...job, ok: false, stage, problems } }));
}
return jobs.map(job => ({ json: job }));

// Looks at every clip status and decides one state for the whole batch:
// done (all COMPLETED), failed (a clip errored), timed_out, or running (check again).
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Set Walkthrough Configurations').first().json;
const jobs = $('Check Clip Jobs Queued').all().map(j => j.json);
const checks = $input.all().map(c => c.json || {});
const started = Math.min(...jobs.map(j => Number(j.submitted_at) || Date.now()));
const minutes = (Date.now() - started) / 60000;
const problems = [];
let done = 0;
const rows = jobs.map((job, i) => {
  const c = checks[i] || {};
  const status = c.status || 'UNKNOWN';
  if (!c.status && c.error) problems.push(`Clip ${job.pair_number}: status check failed (${errText(c.error)}).`);
  else if (status === 'COMPLETED' && c.error) problems.push(`Clip ${job.pair_number} (${job.clip_label}) failed on fal: ${errText(c.error)}${c.error_type ? ` [${c.error_type}]` : ''}`);
  else if (status === 'COMPLETED') done++;
  return { ...job, status, queue_position: c.queue_position ?? null };
});
let state = 'running';
if (problems.length) state = 'failed';
else if (done === jobs.length) state = 'done';
else if (minutes > Number(s.timeout_minutes)) {
  state = 'timed_out';
  problems.push(`Kling took longer than ${s.timeout_minutes} minutes (${done} of ${jobs.length} clips finished).`);
}
return rows.map(r => ({
  json: { ...r, state, stage: 'Kling render', clips_done: done, clips_total: jobs.length, minutes_elapsed: Math.round(minutes * 10) / 10, problems },
}));

// One item with the clip URLs in walkthrough order, ready for the merge.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const jobs = $('Evaluate Clip Completion').all().map(j => j.json);
const results = $input.all().map(r => r.json || {});
const problems = [];
const urls = jobs.map((job, i) => {
  const r = results[i] || {};
  const url = r.video && r.video.url;
  if (!url) problems.push(`Clip ${job.pair_number} (${job.clip_label}): no video in the fal result (${errText(r.error) || errText(r.detail) || 'empty response'}).`);
  return url || '';
});
return [{ json: { ok: problems.length === 0, stage: 'Kling results', problems, video_urls: urls, clips: urls.length } }];

// Checks the merged file before it goes to SocialRobot. Duration comes from the MP4 header (mvhd box).
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Set Walkthrough Configurations').first().json;
const merge = $('Post to fal for Clip Merge').first().json || {};
const item = $input.first();
const video = item.binary && item.binary.data;
const problems = [];
let sizeMb = 0;
let seconds = null;
if (!merge.video || !merge.video.url) {
  problems.push(`fal could not merge the clips (${errText(merge.error) || errText(merge.detail) || 'no video URL returned'}).`);
} else if (!video) {
  problems.push(`The merged video could not be downloaded (${errText(item.json.error) || 'no file'}).`);
} else {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  sizeMb = buf.length / 1048576;
  const i = buf.indexOf('mvhd');
  if (i > 3) {
    const v1 = buf[i + 4] === 1;
    const scale = buf.readUInt32BE(i + (v1 ? 24 : 16));
    const units = v1 ? Number(buf.readBigUInt64BE(i + 28)) : buf.readUInt32BE(i + 20);
    if (scale) seconds = Math.round((units / scale) * 10) / 10;
  }
  const type = String(video.mimeType || '');
  if (!/video\/(mp4|quicktime)/.test(type) && !/\.(mp4|mov)$/i.test(video.fileName || '')) problems.push(`Unexpected file type ${type || 'unknown'}.`);
  if (sizeMb > Number(s.max_file_mb)) problems.push(`File is ${sizeMb.toFixed(1)} MB, above the ${s.max_file_mb} MB limit.`);
  if (seconds === null) problems.push('Could not read the video duration.');
  else if (seconds < Number(s.min_seconds) || seconds > Number(s.max_seconds)) problems.push(`Video is ${seconds} s; allowed is ${s.min_seconds}-${s.max_seconds} s.`);
}
return [{
  json: { ok: problems.length === 0, stage: 'Video check', problems, size_mb: Math.round(sizeMb * 100) / 100, duration_seconds: seconds, video_url: (merge.video && merge.video.url) || '' },
  binary: item.binary,
}];

// One readable reason for whatever went wrong. Add an error workflow in the settings to get alerts.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Set Walkthrough Configurations').first().json;
const f = $('When Listing Submitted Trigger').first();
const j = $input.first().json || {};
let message;
if ($('Put Cancel to fal for Clip Jobs').isExecuted) {
  const src = $('Evaluate Clip Completion').isExecuted ? $('Evaluate Clip Completion').first().json : $('Check Clip Jobs Queued').first().json;
  message = `Kling clips stopped (${src.stage || 'Kling'}): ${(src.problems || []).join(' ')} Unfinished fal jobs were sent a cancel request.`;
} else if (Array.isArray(j.problems) && j.problems.length) {
  message = `${j.stage || 'Check'} failed: ${j.problems.join(' ')}`;
} else if (j.error && $('Create TikTok Draft Walkthrough').isExecuted) {
  message = `SocialRobot could not save the TikTok draft: ${errText(j.error)}`;
} else if (!$('Prepare Photos for Walkthrough').isExecuted) {
  const count = Object.values(f.binary || {}).filter(b => String(b.mimeType || '').startsWith('image/')).length;
  message = `Upload ${Math.max(3, Number(s.min_photos))}-${s.max_photos} listing photos (JPG, PNG or WebP). The form had ${count}.`;
} else {
  message = `Unexpected failure: ${JSON.stringify(j).slice(0, 500)}`;
}
return [{ json: { message, address: f.json['Property Address'] || '' } }];
